from pathlib import Path
import json,re,html
from xml.etree import ElementTree as E
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'dist'; DATA=json.loads((ROOT/'source/catalogue.json').read_text()); SOURCES=json.loads((ROOT/'source/card-sources.json').read_text()); OLD=(ROOT/'source/pixie-original.html').read_text()
h=html.escape
byid={d['id']:d for d in DATA}
BASE='https://decks.loptrlab.com'
pages=[]
BOTNAMES={'pixie':'PIXIE','rift':'The Rift','violet':'Violet / Violet_88','pennywise-violet':'Violet & Pennywise','none':'No dedicated bot verified'}
FAV=re.search(r'<link rel="icon"[^>]*>',OLD).group()
def shell(title,body,path='/',active='Collection',desc='Explore Loptr Lab’s decks, their worlds, rules, variants and companion bots.'):
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if label==active else '')+f'>{label}</a>' for label,url in [('Collection','/'),('Worlds & variants','/variants/'),('Bots & guides','/bots/'),('The studio','/studio/'),('Sources','/sources/')])
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{h(title)} · The Deck Collection</title><meta name="description" content="{h(desc,quote=True)}"><link rel="canonical" href="{BASE}{path}">{FAV}<link rel="stylesheet" href="/codex.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="wordmark" href="/">THE DECK COLLECTION<span>LOPTR LAB · DECKS / WORLDS / COMPANIONS</span></a><nav aria-label="Main navigation">{nav}</nav></header><main id="main">{body}</main><footer><a class="wordmark" href="/">THE DECK COLLECTION</a><p>A living collection by Loptr Lab / IBLoud.xyz.<br>Designs in development. Each entry carries its own status.</p><div><a href="https://codex.loptrlab.com/">Visit PIXIE’s Codex</a><br><a href="/sources/">Read the source record</a></div></footer></body></html>'''
def write(path,title,body,active='Collection',desc=None):
 p=OUT/path.strip('/')/'index.html' if path!='/' else OUT/'index.html';p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(shell(title,body,path,active,**({'desc':desc} if desc else {})));pages.append(path)
def label(t):return f'<span class="status">{h(t)}</span>'
def decklink(i):return f'/decks/{i}/'
def tile(d):
 if d.get('image'): visual=f'<img src="/assets/{d["image"]}" alt="{h(d["imageAlt"])}" loading="lazy" width="1024" height="1536">'
 else: visual=f'<span class="folio">{h(d["family"].upper())}</span><span class="deck-mark" aria-hidden="true">{h(d["mark"])}</span><span class="deck-count">{h(d["count"])} <small>{'ARCHIVED CARDS' if d['id']=='paragon' else 'CARDS'}</small></span><span class="folio">{h(d["specimen"][0][1])}</span>'
 return f'<article class="catalogue-card {d["color"]}"><a class="cover" href="{decklink(d["id"])}" aria-label="Explore {h(d["name"])}">{visual}</a><div class="card-copy">{label(d["status"])}<h3><a href="{decklink(d["id"])}">{h(d["name"])}</a></h3><p>{h(d["tagline"])}</p><span class="caption">{h(d["world"])}</span></div></article>'
def group(ids):return '<div class="catalogue-grid">'+''.join(tile(byid[i]) for i in ids)+'</div>'
hero='''<section class="opening"><div><p class="eyebrow">The collection · 11 deck entries</p><h1>Every deck<br>has a world.</h1><p class="lead">Cards for play, stories for the table, and guides who belong to their worlds. Follow the thread from a familiar suit to a different way of playing.</p><div class="actions"><a class="button primary" href="#collection">Explore the collection</a><a class="button" href="/variants/">Follow the connections</a></div><p class="caption intro-note">With PIXIE as your guide. Artwork, written designs and prototypes are identified throughout.</p></div><figure class="hero-image"><img src="/assets/pixie-suits.png" alt="Four existing PIXIE card studies: a heart lantern, a club flower, a repaired diamond and a spade doorway." width="1881" height="836"><figcaption>PIXIE · transformation-card concept studies</figcaption></figure></section>'''
collection='''<section id="collection"><div class="section-heading"><div><p class="eyebrow">01 / The collection</p><h2>Choose a deck.<br>Enter its story.</h2></div><p>Each entry brings its card system, visual direction, game relationship and companion into one place. Text specimens show recorded designs where finished illustrations are still open.</p></div><nav class="jump-links" aria-label="Collection families"><a href="#pixie">PIXIE</a><a href="#sealed">The Sealed Deck</a><a href="#games">Game decks</a><a href="#tarot">Tarot</a></nav>'''
for ident,name,sub,ids in [('pixie','PIXIE','Two companion decks, one nonhuman guardian.',['pixie-playing','pixie-oracle']),('sealed','The Sealed Deck','One four-suit structure, five documented interpretations.',['sealed-deck','sufi-tariqah','kemetic-dynasty','shinbi-tactics','fifth-sun']),('games','At the game table','Three distinct card systems and the worlds they serve.',['violets-revenge','float-cards','break-the-grid']),('tarot','The narrative arc','Original hero-card research, with its historical tarot archive preserved.',['paragon'])]:
 collection+=f'<div class="family" id="{ident}"><div class="family-heading"><h3>{name}</h3><p>{sub}</p></div>{group(ids)}</div>'
collection+='</section>'
write('/','Loptr Lab’s deck collection',hero+collection+'''<section class="closing"><p class="eyebrow">A thread worth following</p><h2>Her deck. His system.<br>A kingdom still to be designed.</h2><p>The Sufi Tariqah and Systems Quartet meet in the Weaver’s open design problem: how two different ways of understanding power can learn to work together.</p><a class="button" href="/variants/#systems-quartet">Explore the Dueling Systems</a></section><aside class="pixie-note"><strong>PIXIE’s note</strong><p>A written rule, an illustrated card and a running game are different milestones. You’ll find the evidence beside each deck.</p><a href="/studio/">Make with us</a></aside>''')
# Rules are transcribed from the inspected source, without merging court lore into their mechanical meanings.
war=[]; suit=''
for line in SOURCES['war'].splitlines():
 if line.startswith('## '):
  for sig in ['♠','♥','♦','♣']:
   if sig in line:suit=sig
 if re.match(r'\| \*\*\d+',line):
  cols=[c.strip().replace('**','') for c in line.strip('|').split('|')];war.append((suit+cols[0],cols[1],cols[2]))
faces=re.findall(r'### ([JQKA]) — ([^\n]+)\n([^#]+?)(?=\n###|\n---)',SOURCES['war'],re.S)
for sig in ['♠','♥','♦','♣']:
 for rank,name,text in faces:war.append((sig+rank,name,text.strip().replace('**','')))
assert len(war)==52,len(war)
def rulecards(rows):
 return '<div class="rule-grid">'+''.join(f'<article class="rule-card"><span class="card-code">{h(code)}</span><h3>{h(name)}</h3><p>{h(text)}</p></article>' for code,name,text in rows)+'</div>'
for d in DATA:
 path=decklink(d['id'])
 body=f'<div class="breadcrumb"><a href="/">Collection</a><span>/</span>{h(d["family"])}</div><section class="deck-opening {d["color"]}"><div><p class="eyebrow">{h(d["world"])}</p><h1>{h(d["name"])}</h1><p class="lead">{h(d["tagline"])}</p><p>{h(d["description"])}</p><div class="metadata"><strong>{h(d.get("countLabel",d["count"]+" cards"))}</strong>{label(d["status"])}</div></div>'
 if d.get('image'):body+=f'<figure class="detail-art"><img src="/assets/{d["image"]}" alt="{h(d["imageAlt"])}" width="1024" height="1536"><figcaption>Existing concept art · final card faces in development</figcaption></figure>'
 else:body+='<div class="specimen"><p class="eyebrow">From the design record</p>'+rulecards(d['specimen'])+'<p class="caption">Typeset reference specimens · not finished card artwork</p></div>'
 body+='</section>'
 body+=f'<section class="relationship-grid"><article><p class="eyebrow">The world & variant</p><h2>Where it belongs</h2><p>{h(d["variant"])}</p><a href="/variants/">Explore the variant index</a></article><article><p class="eyebrow">The companion</p><h2>{h(BOTNAMES[d["bot"]])}</h2><p>{h(d["botNote"])}</p><a href="/bots/#{d["bot"]}">Read the companion record</a></article><article><p class="eyebrow">The visual language</p><h2>Design & artwork</h2><p>{h(d["art"])}</p></article></section>'
 if d.get('court'):
  body+='<section><p class="eyebrow">The authored court</p><h2>Four suits, twelve figures.</h2><p>Character assignments from the design bible. These lore associations are kept separate from the legacy universal face-card rules.</p><div class="table-scroll"><table><caption>Court assignments by suit</caption><thead><tr><th>Suit / domain</th><th>King</th><th>Queen</th><th>Jack</th></tr></thead><tbody>'+''.join('<tr>'+''.join(f'<{ "th scope="+chr(34)+"row"+chr(34) if j==0 else "td"}>{h(c)}</{ "th" if j==0 else "td"}>' for j,c in enumerate(row))+'</tr>' for row in d['court'])+'</tbody></table></div></section>'
 if d['id'] in ['sealed-deck','violets-revenge']:
  body+='<section id="cards"><p class="eyebrow">The card reference</p><h2>All 52 Cards of War.</h2><p>Preserved from the legacy dice/card/chess design. RP, HP and Phase III belong to that system; these are not the current four-player Veiled Dominion rules.</p><details><summary>Open the complete 52-card text reference</summary>'+rulecards(war)+'</details></section>'
 if d['id']=='break-the-grid':
  cards=re.findall(r'### ([BCRV]\d) — ([^\n]+)\n\n(.*?)(?=\n###|\n##|\Z)',SOURCES['grid'],re.S)
  assert len(cards)==16
  body+='<section id="cards"><p class="eyebrow">The complete paper prototype</p><h2>Sixteen cards. Two choices each.</h2><p>Initial setup: two players, one card each, draw one at the start of a turn, hand limit three. Play one card instead of a normal action; choose one path and discard it. Reshuffle the discard pile once.</p><p>Players may decline, exchange or discard an uncomfortable card without penalty. Values are provisional; this is an arts-and-engagement prototype, not a clinical tool.</p>'+rulecards([(c,n,t.strip().replace('**','')) for c,n,t in cards])+'<p><a href="https://github.com/ibloud/inpatient-corridors-review/blob/main/BREAK-THE-GRID-DECK.html">Open the printable review-sheet source</a></p></section>'
 if d['id']=='paragon':
  body+=(ROOT/'source/original-direction.html').read_text()
  checklist=SOURCES['paragon'].split('### 3B — THE 78-CARD MASTER CHECKLIST')[1].split('## PART 4')[0]
  rows=[];typ=''
  for line in checklist.splitlines():
   if line.startswith('**') and 'cards)' in line:typ=line.replace('**','')
   if line.startswith('|'):
    cols=[c.strip() for c in line.strip('|').split('|')]
    if cols[0] in ['#','Card'] or cols[0].startswith('-'):continue
    if len(cols)==3:rows.append((cols[0],cols[1],cols[2]))
    elif len(cols)==2:rows.append((cols[0],typ.split(' (')[0].title(),cols[1]))
  assert len(rows)==78,len(rows)
  body+='<section id="cards"><p class="eyebrow">Historical research only</p><h2>The archived 78-card assignments.</h2><p>These earlier Paragon assignments are an adaptation archive, not the new production roster or verified canon for every imagined scene. Do not import this archive into the new story generator. Its symbolic assignments do not determine gameplay strength or provide production rights.</p><details><summary>Open the 78 historical assignments</summary>'+rulecards(rows)+'</details><p class="note">Paragon character references are presented as design provenance. No merchandise approval or artist endorsement is represented.</p></section>'
 if d['id'].startswith('pixie'):
  tale=re.search(r'<section id="tale">.*?</section>',OLD,re.S).group()
  body+=tale.replace('id="practice-prompt"','id="practice-prompt" aria-live="polite"')+'<script src="/reflection.js" defer></script>'
 body+=f'<section class="source-note"><p class="eyebrow">Source record</p><p>{h(d["source"])}</p>'+(f'<a href="{h(d["sourceUrl"])}">Read the public source</a> · ' if d['sourceUrl'] else '')+'<a href="/sources/">See reconciliation notes</a></section>'
 body+='<section><p class="eyebrow">Continue through the collection</p><h2>Connected decks</h2>'+group(d['related'])+'</section>'
 write(path,d['name'],body,desc=d['description'])
# Variant index: boards and future conversions stay distinguishable from documented card decks.
variants=[
('original-tarot','Original hero-card experiment','Design merged · receiving contract under review','Return to the Void develops independent characters, tactical modifiers and consequential authored choices. One original hero, one modifier and one choice is the first playable milestone. Paragon-Reborn #17 is merged; Engine #53 remains draft. No runtime mechanics, canonical four-player rules, PIXIE identity or unrelated bots change through this documentation.','Return to the Void · historical Paragon deck archived','No implemented game bot','https://github.com/Loptr-Lab/veiled-dominion-engine/pull/53'),
('systems-quartet','The Systems Quartet','Board model · card conversion open','The King’s side of the Dueling Systems: Cannon’s Biome, Coulter’s Cybernetic Loop, Veblen’s Leisure Class and Fresco’s Resource Economy. The design currently uses open board information. Its personal-deck conversion and shared rules with Sufi Tariqah remain an open problem.','Sufi Tariqah / The Weaver','No dedicated bot verified','https://github.com/Loptr-Lab/duet-solo-hackathon/blob/main/docs/design/dueling-systems.md'),
('veiled-dominion','Veiled Dominion','Canonical design target','The four-player, 14×14 cross-board game has its own GDD and rulebook. The Sealed Deck and older dice/card/chess work are part of its design history; their mechanics do not automatically become current canon.','Sealed Deck / 52 Cards of War','The Rift: posting source; Sealed Deck narration proposed','https://github.com/Loptr-Lab/veiled-dominion-engine/blob/main/docs/CANON_AND_CONTINUITY.md'),
('duet','Duet: Solo','Experimental game','A separate two-player, 8×8 mechanics lab. The Weaver connects the personal decks narratively, while PIXIE provides bounded fixed-answer help in source. Current serving revision and accessibility acceptance require their own evidence.','Sufi Tariqah / Systems Quartet relationship in design','PIXIE / The Rift','https://github.com/Loptr-Lab/duet-solo-hackathon'),
('inpatient','Inpatient Corridors / Break the Grid','16-card paper prototype','The earlier phase-shifting pressure concept developed into an independent module with Boundary, Connection, Resource and Voice cards. The compact deck retains its own setup and provisional balance.','Break the Grid','No deck-specific bot verified','https://github.com/ibloud/inpatient-corridors-review'),
('derry','Back in Derry / Sewers & Shadows','Permission-dependent historical reference','The horror reference study and Violet/Pennywise exhibition history are documented. Float Cards has a separate standard-pack engine. The retired Discord deployment is not an available play service.','Float Cards','Violet / Pennywise · retired service','https://github.com/Loptr-Lab/veiled-dominion-engine/blob/main/docs/variants/case-studies/BACK_IN_DERRY_REFERENCE.md'),
('dread-pressure','Dread Pressure','Original model · documentation only','A later original variant studies movement pressure through a Lure token. It is a systems-design example, not a completed card deck or a promoted canonical rule.','Related board experiment; no deck defined','No bot verified','https://github.com/Loptr-Lab/veiled-dominion-engine/blob/main/docs/variants/examples/DREAD_PRESSURE.md'),
('corrupted-rom','Corrupted ROM','Incubating · documentation only','The current original abstraction uses damaged-digital presentation with a required Safe Mode and stable rules information. The earlier SICKBOI.EXE document remains historical inspiration, not a claim of artist participation.','Related presentation variant; no deck defined','No bot verified','https://github.com/Loptr-Lab/veiled-dominion-engine/blob/main/docs/variants/incubation/CORRUPTED_ROM.md'),
('gallery','Dark Bauhaus / Gallery Edition','Board design concept','A design study where geometry communicates piece movement and state. It is a physical/digital board direction, not an independently specified deck.','Veiled Dominion visual study','No bot verified',''),
('street','Street Level / Syndicate','Board design concept','An urban visual treatment explores visibility, shelter and restraint. No separate card list or dedicated bot was verified.','Veiled Dominion visual study','No bot verified',''),
('paracausal','The Paracausal Edition','Historical reference study','A science-fiction light/dark mapping exists in the planning archive. It is recorded here as a reference study; no standalone deck, bot or licensed release was verified.','Veiled Dominion reference study','No bot verified',''),
('space','Space / Aether fifth suit','Exploratory note','The archive explores a fifth tarot suit associated with space. It has no complete card list and is not added to the existing Paragon 78-card count.','Tarot design exploration','No bot verified','')]
vbody='<section class="page-title"><p class="eyebrow">02 / Worlds & variants</p><h1>Follow the thread.</h1><p class="lead">A deck can carry a different court, belong to a game, or point toward a system still being designed. The connections matter as much as the names.</p></section><section><h2>One Sealed Deck, five interpretations.</h2><div class="link-grid">'+''.join(f'<a href="{decklink(i)}">{h(byid[i]["name"])}<span>{h(byid[i]["status"])}</span></a>' for i in ['sealed-deck','sufi-tariqah','kemetic-dynasty','shinbi-tactics','fifth-sun'])+'</div></section>'
for ident,name,status,desc,decks,bots,url in variants:
 vbody+=f'<section class="variant-row" id="{ident}"><div><p class="eyebrow">{h(status)}</p><h2>{h(name)}</h2></div><div><p>{h(desc)}</p><dl><dt>Deck connection</dt><dd>{h(decks)}</dd><dt>Companion connection</dt><dd>{h(bots)}</dd></dl>'+ (f'<a href="{url}">Read the source</a>' if url else '<span class="caption">Source: Drive design archive, inspected October 8, 2026.</span>')+'</div></section>'
write('/variants/','Worlds & variants',vbody,'Worlds & variants')
bots=[('pixie','PIXIE','Guide character · fixed help in Duet source','PIXIE stays constant across the collection: a nonhuman guide who observes, offers context and leaves the choice with you. Duet source contains eight fixed game-help answers and an Outside Support fallback. Those answers make no model call. The deck’s interactive guide remains a design direction.',['pixie-playing','pixie-oracle'],'https://github.com/Loptr-Lab/duet-solo-hackathon/blob/main/README.md'),('rift','The Rift','Match-posting source · live operation unverified','The Rift connects game events and the authored lore archive. Duet contains match-posting code; its current README leaves live configuration and successful posting unverified. The older Drive engagement plan proposes richer lore and Sealed Deck event types. Those plans are not treated here as running services.',['sealed-deck','sufi-tariqah','kemetic-dynasty','shinbi-tactics','fifth-sun'],'https://github.com/Loptr-Lab/duet-solo-hackathon/blob/main/atprotoPoster.js'),('violet','Violet / Violet_88','Retired Discord source · browser and gamemaster proposals','Violet’s clinical forensic voice belongs to her own story world. The Roomy transition preserves bot source for possible opt-in browser reuse. The Drive Violet_88 document separately proposes an agent gamemaster. Neither proposal establishes a working browser or Roomy bot.',['violets-revenge'],'https://github.com/ibloud/violets-revenge/blob/main/docs/ROOMY-TRANSITION.md'),('pennywise-violet','Violet & Pennywise','Historical play modes · service retired','Float Cards source includes human-versus-Pennywise and autonomous Violet-versus-Pennywise exhibition modes. Rules and card selection are separate from persona narration. The October 4 retirement record reports zero running replicas for the Discord service. Third-party character references remain permission-dependent.',['float-cards','violets-revenge'],'https://github.com/ibloud/sewers-and-shadows-bot/blob/main/bot/src/index.js'),('none','Open companion roles','No deck-specific bot verified','The scan found no dedicated bot for Break the Grid, Paragon Tarot, Systems Quartet or the other board-only studies. A future bot must be attached to its actual ruleset and evidenced separately from a character description.',['break-the-grid','paragon'],'')]
bbody='<section class="page-title"><p class="eyebrow">03 / Bots & guides</p><h1>Meet the companions.</h1><p class="lead">A narrator gives a game a voice. A rules engine decides what can happen. These records show where each companion belongs and what exists today.</p></section>'
for ident,name,status,desc,ids,url in bots:
 bbody+=f'<section class="variant-row" id="{ident}"><div><p class="eyebrow">{h(status)}</p><h2>{h(name)}</h2></div><div><p>{h(desc)}</p><div class="jump-links">'+''.join(f'<a href="{decklink(i)}">{h(byid[i]["name"])}</a>' for i in ids)+'</div>'+ (f'<a href="{url}">Read implementation / status</a>' if url else '')+'</div></section>'
write('/bots/','Bots & guides',bbody,'Bots & guides')
# Preserve the existing functional creator and cost tools under the shared site navigation.
studio_sections=''.join(re.findall(r'<section\b.*?</section>',OLD,re.S)[1:])
studio_sections=studio_sections.replace('src="assets/','src="/assets/').replace('id="practice-prompt"','id="practice-prompt" aria-live="polite"')
script=re.search(r'<script>(.*?)</script>',OLD,re.S).group(1)
(OUT/'studio-tools.js').write_text(script)
oldcss=re.search(r'<style>(.*?)</style>',OLD,re.S).group(1)
(OUT/'studio-legacy.css').write_text(oldcss)
studio='<link rel="stylesheet" href="/studio-legacy.css"><link rel="stylesheet" href="/studio-overrides.css"><section class="page-title"><p class="eyebrow">04 / The studio</p><h1>Make with care.<br>Keep the credit.</h1><p class="lead">Bring a craft, test a deck or make a story of your own. The existing PIXIE introduction and two-deck budget tools remain here, with their assumptions visible.</p></section>'+studio_sections+'<script src="/studio-tools.js" defer></script>'
write('/studio/','The studio',studio,'The studio')
(OUT/'reflection.js').write_text("const prompts=['What did you notice before deciding what it means?','Whose perspective is missing from this story?','What repair is yours to offer—and yours to decline?','Where is the visible exit from this commitment?','What note would help you return after an interruption?'];let index=0;document.getElementById('next-prompt').addEventListener('click',()=>{index=(index+1)%prompts.length;document.getElementById('practice-prompt').textContent=prompts[index]});")
sourcebody='''<section class="page-title"><p class="eyebrow">05 / Provenance</p><h1>Keep the trail visible.</h1><p class="lead">This edition reconciles Google Drive design records with current GitHub documentation and source, inspected October 8, 2026.</p></section><section><h2>What the labels mean</h2><div class="relationship-grid"><article><h3>Visual studies</h3><p>Existing artwork demonstrates a direction. It does not establish a complete set of card faces.</p></article><article><h3>Documented design</h3><p>Card text, court assignments or a visual brief exists. Production and playtesting are separate milestones.</p></article><article><h3>Engine source</h3><p>Implementation was found in a repository. A working public service requires separate deployment evidence.</p></article></div></section><section><h2>Where the records disagree</h2><details><summary>Clubs court and missing pip cards</summary><p>An older Dueling Systems handoff calls the base Clubs royals and pips 3–9 missing. The August Court Card Bible supplies Ptah, Seshat and Imhotep; the full card database and reference PDF include Clubs 3–9. The catalogue uses those records and keeps the discrepancy visible.</p></details><details><summary>Court lore and universal face-card powers</summary><p>The court bible associates mythic characters with named powers. The legacy mechanical database uses universal J, Q, K and A rules across every suit. These layers have not been merged into a new ruleset here.</p></details><details><summary>Deck history and current Veiled Dominion canon</summary><p>The current four-player, 14×14 GDD and rulebook govern canonical mechanics. The older dice/card/chess system, cultural reskins and Duet experiments do not change that authority.</p></details><details><summary>Bot source, older plans and current availability</summary><p>The older Rift document says event posting was live. Current Duet documentation leaves live configuration and successful posts unverified. The October 4 Roomy transition records both identified Discord services shut down, while browser reuse is proposed.</p></details><details><summary>Artwork, interpretation and publication</summary><p>The three PIXIE images are existing AI-generated concept studies. Text specimens throughout the collection display recorded card information; they are not newly discovered illustrations. Cultural editions present authored creative interpretations. Third-party character references do not imply affiliation or merchandise permission.</p></details></section><section><h2>Read the public records</h2><ul class="source-list">'''
public=[('Violet card design guide','https://github.com/ibloud/violets-revenge/blob/main/CARD-DESIGN-GUIDE.md'),('Complete 52-card database','https://github.com/ibloud/violets-revenge/blob/main/CARD-TEXT-DATABASE.md'),('Dueling Systems handoff','https://github.com/Loptr-Lab/duet-solo-hackathon/blob/main/docs/design/dueling-systems.md'),('Current canon and continuity','https://github.com/Loptr-Lab/veiled-dominion-engine/blob/main/docs/CANON_AND_CONTINUITY.md'),('Variant registry','https://github.com/Loptr-Lab/veiled-dominion-engine/blob/main/docs/variants/VARIANT_REGISTRY.yml'),('Break the Grid: sixteen cards','https://github.com/ibloud/inpatient-corridors-review/blob/main/BREAK-THE-GRID-DECK.md'),('Paragon: 78-card handoff','https://github.com/ibloud/Paragon-Reborn/blob/main/docs/paragon-tarot-research.md'),('Float Cards engine','https://github.com/ibloud/sewers-and-shadows-bot/blob/main/bot/float-cards-engine.js'),('Roomy transition and bot retirement','https://github.com/ibloud/violets-revenge/blob/main/docs/ROOMY-TRANSITION.md'),('Duet / PIXIE implementation status','https://github.com/Loptr-Lab/duet-solo-hackathon/blob/main/README.md')]
sourcebody+=''.join(f'<li><a href="{url}">{h(name)}</a></li>' for name,url in public)+'</ul></section><section><h2>The design archive</h2><p>Drive records inspected include the Sealed Deck Court Card Bible, Global Mythological Skins, Sufi Tariqah, design requirements, Systems Quartet, Inpatient Corridors, the visual-variant briefs, Violet_88 proposal, Rift engagement plan, Paragon workbook, Deck Design Notes, Queen’s Journey and the Space/Aether exploration.</p><p>The catalogue publishes relevant design summaries. Raw private documents, invitation details and operational credentials are not part of the public site.</p></section>'
